using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using EFT;
using EFT.InventoryLogic;
using UnityEngine;
namespace LocalSpt5Esp;
internal static partial class RaidCommands {
 static bool Extended(GameWorld w,string command,string[] a,JsonElement? options){
  if(command=="item"&&a[0]=="inspect"){foreach(var p in Resolve(w,a[2])){var item=CommandItem(p,a[3]);RaidChat.Output(JsonSerializer.Serialize(new{owner=Name(p),id=item.Id,template=item.StringTemplateId,count=item.StackObjectsCount,parameters=LoadoutPlans.Parameters(item).Attributes(),attachments=LoadoutPlans.CaptureItem(item),contents=LootDisplay.Children(item).Select(c=>new{id=c.Id,template=c.StringTemplateId,count=c.StackObjectsCount}),weapon=item.TryCast<Weapon>() is {} gun?WeaponEditor.CommandInspect(gun):null}));}return true;}
  if(options!=null&&(command is "give" or "loot" or "item")&&(command=="give"||command=="loot"&&a[0]=="spawn"||command=="item"&&a[0]=="replace")){
   int templateIndex=command=="give"?1:command=="loot"?4:5;int count=a.Length>templateIndex+1?Integer(a[templateIndex+1],1,100000):1;
   var spec=new ItemSpec(Template(a[templateIndex]),1,options);var targets=command=="loot"?new[]{w.MainPlayer}:Resolve(w,a[command=="item"?2:0]);
   var plans=new List<(Player Owner,Item Item,ItemAddress? Address)>();using var budget=new BuildBudget();
   foreach(var p in targets){int left=count;while(left>0){var item=BuildSpecified(spec,p,budget:budget);item.StackObjectsCount=Math.Min(left,Math.Max(1,item.StackMaxSize));left-=item.StackObjectsCount;
    ItemAddress? address=null;if(command=="item"){var slot=Slot(p,a[3]);if(slot.ContainedItem!=null)throw new ArgumentException("目标槽需为空；未移除旧装备。");if(left>0)throw new ArgumentException("装备槽最多一个堆叠。");address=slot.CreateItemAddress();if(!ItemManipulator.Add(item,address,p.InventoryController,true).Succeeded)throw new ArgumentException("装备槽不兼容。");}
    plans.Add((p,item,address));if(plans.Count>(command=="loot"?32:100))throw new ArgumentException("本次生成堆叠过多，请减少数量。");
   }}
   int added=0;Vector3 point=command=="loot"?Coordinates(w,a[1..4]):default;
   foreach(var plan in plans){if(command=="loot"){w.ThrowItem(plan.Item,w.MainPlayer.Cast<IPlayer>(),point+Vector3.up*(.15f+added*.03f),Quaternion.identity,Vector3.zero,Vector3.zero,true,true,0);budget.Keep(plan.Item);added++;continue;}
    var address=plan.Address??GiveAddress(plan.Owner,plan.Item);if(address==null){RaidChat.Output("空间不足，已完成 "+added+" 个堆叠；未放入的物品已丢弃。");return true;}
    plan.Owner.InventoryController.AddAndRaiseEvents(plan.Item,address);if(plan.Item.CurrentAddress==null)throw new ArgumentException("物品放入后回读失败，之前已完成的物品不会自动回滚。");budget.Keep(plan.Item);added++;plan.Owner.Profile.Inventory.Equipment.RaiseRefreshEvent(false,true);
   }RaidChat.Output("已生成 "+added+" 个堆叠（含详细参数）。枪械数值仅本局该实例生效。");return true;
  }
  if(options is not {} o){if(command=="item"&&a[0]=="modify"&&a.Length==4||command=="ai"&&a[0]=="configure")throw new ArgumentException("请在末尾提供 JSON 配置。");return false;}
  switch(command){
   case "item":ModifySpecified(w,a,o);return true;
   case "summon":SummonSpecified(w,a,o);return true;
   case "ai":if(a[0]!="configure")throw new ArgumentException("详细AI配置请使用 /ai configure <AI> {配置}。");ConfigureActors(w,a[1],o);return true;
   case "heal":HealSpecified(w,a,o);return true;
   case "repair":RepairSpecified(w,a,o);return true;
   case "reload":Reload(w,a,(int)(o.TryGetProperty("count",out _)?ChatCommandOptions.Number(o,"count",1,100000,true):100000));return true;
   case "clear":ClearSpecified(w,a,o);return true;
   case "weather":Weather(a,o);return true;
   case "tp":case "teleport":if(a.Contains("facing"))throw new ArgumentException("facing 与 yaw/pitch 配置不能同时使用。");float? yaw=o.TryGetProperty("yaw",out _)?(float)ChatCommandOptions.Number(o,"yaw",-360000,360000):null,pitch=o.TryGetProperty("pitch",out _)?(float)ChatCommandOptions.Number(o,"pitch",-89,89):null;var actors=a.Length is 2 or 4?Resolve(w,a[0]):new[]{w.MainPlayer};Teleport(w,a);foreach(var p in actors){var r=p.Rotation;float y=yaw??r.x,t=pitch??r.y;if(p.IsYourPlayer)p.Rotation=new(y,t);else AiSceneDirector.Apply(w,p,AiSceneDirector.For(p) with{Enabled=true,SetFacing=true,Yaw=y,Pitch=t});}return true;
   default:throw new ArgumentException("此子命令没有扩展配置。");
  }
 }
 static int Integer(string value,int min,int max){double n=ChatCommandSyntax.Number(value,min,max);if(n!=Math.Truncate(n))throw new ArgumentException("数量须为整数。");return (int)n;}
 static ItemAddress? GiveAddress(Player p,Item item){foreach(var slot in InventorySlots(p).OrderBy(s=>s.Name=="Backpack"?0:s.Name=="TacticalVest"?1:2)){var bag=slot.ContainedItem?.TryCast<CompoundItem>();if(bag?.Grids==null)continue;foreach(var grid in bag.Grids){var address=grid?.FindLocationForItem(item);if(address!=null&&ItemManipulator.Add(item,address,p.InventoryController,true).Succeeded)return address;}}foreach(var slot in InventorySlots(p))if(slot.ContainedItem==null&&ItemManipulator.Add(item,slot.CreateItemAddress(),p.InventoryController,true).Succeeded)return slot.CreateItemAddress();return null;}
 static Item CommandItem(Player p,string path){var parts=path.Split('/');Item item=Slot(p,parts[0]).ContainedItem??throw new ArgumentException("装备槽为空。");foreach(var part in parts.Skip(1)){if(part.StartsWith("id:")){item=LootDisplay.Children(item).FirstOrDefault(c=>c.Id==part[3..])??throw new ArgumentException("未找到直接子物品 ID。");}else item=item.TryCast<CompoundItem>()?.Slots?.FirstOrDefault(s=>s?.ID==part)?.ContainedItem??item.TryCast<Weapon>()?.Chambers?.FirstOrDefault(s=>s?.ID==part)?.ContainedItem??throw new ArgumentException("不存在附件路径："+part);}return item;}
 static void ModifySpecified(GameWorld w,string[] a,JsonElement o){if(a[0]!="modify"||a.Length!=4)throw new ArgumentException("/item modify entity <目标> <槽/附件路径> {配置}；不能与旧式单字段参数混用。");if(o.TryGetProperty("contents",out _)||o.TryGetProperty("attachments",out _)||o.TryGetProperty("cartridges",out _))throw new ArgumentException("现有物品修改只支持组件、狗牌和枪械数值；结构配置用于 give、loot spawn 和 item replace。");
  var plans=Resolve(w,a[2]).Select(p=>(Owner:p,Item:CommandItem(p,a[3]))).ToArray();
  foreach(var plan in plans){var sample=BuildItem(plan.Item.StringTemplateId,1);LoadoutPlans.Parameters(plan.Item).Apply(sample);Components(o).Apply(sample);if(o.TryGetProperty("dogtag",out var dogtag))ApplyDogtag(sample,dogtag);if(o.TryGetProperty("weapon",out var weapon)){ChatCommandOptions.Keys(weapon,"values","ignoreAttachments");if(plan.Item.TryCast<Weapon>()==null)throw new ArgumentException("目标不是枪械。");WeaponEditor.CommandTune(plan.Owner,plan.Item.Cast<Weapon>(),WeaponValues(weapon),weapon.TryGetProperty("ignoreAttachments",out _)&&ChatCommandOptions.Bool(weapon,"ignoreAttachments"),true);}}
  foreach(var plan in plans){Components(o).Apply(plan.Item);if(o.TryGetProperty("dogtag",out var dogtag))ApplyDogtag(plan.Item,dogtag);if(o.TryGetProperty("weapon",out var weapon))WeaponEditor.CommandTune(plan.Owner,plan.Item.Cast<Weapon>(),WeaponValues(weapon),weapon.TryGetProperty("ignoreAttachments",out _)&&ChatCommandOptions.Bool(weapon,"ignoreAttachments"));plan.Item.RaiseRefreshEvent(true,true);plan.Owner.Physical?.MarkWeightAsDirty();}RaidChat.Output("已修改 "+plans.Length+" 件物品。");
 }
 static void HealSpecified(GameWorld w,string[] a,JsonElement o){float? amount=o.TryGetProperty("amount",out _)?(float)ChatCommandOptions.Number(o,"amount",0,100000000):null,percent=o.TryGetProperty("percent",out _)?(float)ChatCommandOptions.Number(o,"percent",0,100):null;if(amount!=null&&percent!=null)throw new ArgumentException("amount 与 percent 不能同时使用。");bool clean=!o.TryGetProperty("clearEffects",out _)||ChatCommandOptions.Bool(o,"clearEffects");float? hydration=o.TryGetProperty("hydration",out _)?(float)ChatCommandOptions.Number(o,"hydration",0,1000000):null,energy=o.TryGetProperty("energy",out _)?(float)ChatCommandOptions.Number(o,"energy",0,1000000):null;bool changeHealth=amount!=null||percent!=null||!o.EnumerateObject().Any();var part=a.Length>1?Body(a[1]):EBodyPart.Common;foreach(var p in Resolve(w,a.Length>0?a[0]:"@s")){var health=p.ActiveHealthController;foreach(var body in part==EBodyPart.Common?AiBodyHealth.Parts:new[]{part}){if(clean)health.RemoveNegativeEffects(body);if(!changeHealth)continue;var value=health.GetBodyPartHealth(body,false);float target=percent is {} pct?value.Maximum*pct/100:amount is {} n?Math.Min(value.Maximum,value.Current+n):value.Maximum;health.ChangeHealth(body,target-value.Current,new EFT.Ballistics.DamageInfo());}if(hydration is {} h)health.ChangeHydration(Math.Min(h,health.Hydration.Maximum)-health.Hydration.Current);if(energy is {} e)health.ChangeEnergy(Math.Min(e,health.Energy.Maximum)-health.Energy.Current);}RaidChat.Output("已应用治疗参数。");}
 static Item[] ItemTree(Item root,bool recursive){var result=new List<Item>();var seen=new HashSet<IntPtr>();void Visit(Item item,int depth){if(depth>16||!seen.Add(item.Pointer))return;result.Add(item);if(recursive)foreach(var child in LootDisplay.Children(item))Visit(child,depth+1);}Visit(root,0);return result.ToArray();}
 static void RepairSpecified(GameWorld w,string[] a,JsonElement o){float? current=o.TryGetProperty("durability",out _)?(float)ChatCommandOptions.Number(o,"durability",0,float.MaxValue):null,max=o.TryGetProperty("maxDurability",out _)?(float)ChatCommandOptions.Number(o,"maxDurability",.01,float.MaxValue):null,percent=o.TryGetProperty("percent",out _)?(float)ChatCommandOptions.Number(o,"percent",0,100):null;if(current!=null&&percent!=null)throw new ArgumentException("durability 与 percent 不能同时使用。");bool recursive=!o.TryGetProperty("recursive",out _)||ChatCommandOptions.Bool(o,"recursive");var plans=new List<(Item Item,float Current,float Max)>();foreach(var p in Resolve(w,a[0])){var items=a.Length>1?ItemTree(CommandItem(p,a[1]),recursive):recursive?InventoryItems(p):InventorySlots(p).Where(s=>s.ContainedItem!=null).Select(s=>s.ContainedItem).ToArray();foreach(var item in items){var repair=item.GetItemComponent<RepairableComponent>();if(repair==null)continue;float m=max??repair.MaxDurability,c=current??(percent is {} pct?m*pct/100:m);if(c>m)throw new ArgumentException("当前耐久不能超过最大耐久。");plans.Add((item,c,m));}}foreach(var plan in plans){new ItemComponentParameters{Durability=plan.Current,MaxDurability=plan.Max}.Apply(plan.Item);plan.Item.RaiseRefreshEvent(true,true);}RaidChat.Output("已修复 "+plans.Count+" 件物品。");}
 static void ClearSpecified(GameWorld w,string[] a,JsonElement o){bool? fir=o.TryGetProperty("foundInRaid",out _)?ChatCommandOptions.Bool(o,"foundInRaid"):null;float min=o.TryGetProperty("durabilityMin",out _)?(float)ChatCommandOptions.Number(o,"durabilityMin",0,float.MaxValue):0,max=o.TryGetProperty("durabilityMax",out _)?(float)ChatCommandOptions.Number(o,"durabilityMax",0,float.MaxValue):float.MaxValue;if(min>max)throw new ArgumentException("耐久范围无效。");bool recursive=!o.TryGetProperty("recursive",out _)||ChatCommandOptions.Bool(o,"recursive");string? template=a.Length>1?Template(a[1]):null;int maximum=a.Length>2?Integer(a[2],0,100000):100000;foreach(var p in Resolve(w,a[0])){var items=(recursive?InventoryItems(p):InventorySlots(p).Where(s=>s.ContainedItem!=null).Select(s=>s.ContainedItem).ToArray()).Reverse().Where(i=>(template==null||i.StringTemplateId==template)&&(fir==null||i.SpawnedInSession==fir)&&(min==0&&max==float.MaxValue||i.GetItemComponent<RepairableComponent>() is {} r&&r.Durability>=min&&r.Durability<=max)).ToArray();if(maximum==0){RaidChat.Output(Name(p)+" 匹配数量 "+items.Sum(i=>(long)i.StackObjectsCount));continue;}int removed=0;foreach(var item in items){if(removed>=maximum)break;int n=Math.Min(item.StackObjectsCount,maximum-removed);if(n==item.StackObjectsCount)RemoveItem(p,item);else item.StackObjectsCount-=n;removed+=n;}p.Profile.Inventory.Equipment.RaiseRefreshEvent(false,true);RaidChat.Output(Name(p)+" 已移除 "+removed+"。");}}
}
